use clap::Command;

fn tool() -> Command {
    Command::new("tool")
        .arg(
            clap::Arg::new("pair")
                .long("pair")
                .num_args(1..=3)
                .value_terminator(";")
                .add(clap_complete::engine::ArgValueCandidates::new(|| {
                    vec![
                        clap_complete::engine::CompletionCandidate::new("pair-a"),
                        clap_complete::engine::CompletionCandidate::new("pair-b"),
                        clap_complete::engine::CompletionCandidate::new("pair-c"),
                    ]
                })),
        )
        .arg(
            clap::Arg::new("tail")
                .value_parser(["tail-a", "tail-b", ";x"])
                .num_args(1..),
        )
        .arg(clap::Arg::new("verbose").long("verbose"))
}

